'use client'

import { Loader2 } from 'lucide-react'
import { useDerivedStore } from '@/features/editor/store/useDerivedStore'
import { useWakeLock } from '@/features/editor/hooks/useWakeLock'
import BuilderLimitToast from './BuilderLimitToast'
import BuildViewer from './BuildViewer'

export default function BuilderMain() {
    // Building with physical dice takes a while - don't let the screen sleep
    useWakeLock()

    const diceGrid = useDerivedStore(state => state.grid)

    // The grid is regenerated by the dice pipeline after a restore - show a
    // spinner until it lands. BuildViewer takes a non-null grid so its hooks
    // never have to guard.
    if (!diceGrid) {
        return (
            <div className="w-full h-full flex flex-col items-center justify-center gap-3">
                <Loader2 className="w-8 h-8 animate-spin" style={{ color: 'var(--pink)' }} />
                <span className="text-sm" style={{ color: 'var(--text-secondary)' }}>Preparing your build...</span>
            </div>
        )
    }

    return (
        <div className="relative w-full h-full">
            <BuilderLimitToast />
            <BuildViewer grid={diceGrid} />
        </div>
    )
}
